import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import { apiClient, unwrap, type BffResponse } from '../../services/api';
import { normalizeSearchText } from '../../utils/codeField';
import {
  SEARCH_DROPDOWN_CODE_WIDTH,
  SEARCH_DROPDOWN_PORTAL,
  SEARCH_DROPDOWN_PRIMARY_WIDTH,
} from './searchDropdownDefaults';

/** Lookup đối tượng — `GET /master/customers` (parity Finance/Master). */
export interface CustomerLookupItem {
  customerId: string;
  code: string;
  name: string;
  phone?: string | null;
  customerType?: string | null;
}

interface PagedCustomers {
  items: CustomerLookupItem[];
  page: number;
  totalCount: number;
}

function qs(params: Record<string, string | number | boolean | undefined>): string {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === '') return;
    sp.set(k, String(v));
  });
  return sp.toString();
}

/** SEARCH_REMOTE — danh mục đối tượng. `valueIsCode` vì dòng PKH lưu mã nghiệp vụ. */
export function createCustomerSearchConfig(): SearchInputConfig<CustomerLookupItem> {
  return {
    api: {
      getItemKey: c => c.code,
      search: async ({ search, page, pageSize }) => {
        const q = qs({
          search: search ? normalizeSearchText(search) || undefined : undefined,
          page,
          pageSize,
          isActive: true,
        });
        const res = await apiClient.get<BffResponse<PagedCustomers>>(`/master/customers?${q}`);
        const data = unwrap(res);
        const totalPages = Math.max(1, Math.ceil((data.totalCount || 0) / pageSize));
        return { items: data.items ?? [], page: data.page ?? page, totalPages };
      },
    },
    display: {
      getPrimaryDisplay: c => c.code,
      getSecondaryDisplay: c => c.name,
      getSingleDisplay: c => (c.code && c.name ? `${c.code} — ${c.name}` : c.code || c.name),
    },
    columns: [
      { key: 'code', variant: 'badge', width: SEARCH_DROPDOWN_CODE_WIDTH, render: c => c.code },
      { key: 'name', variant: 'primary', width: SEARCH_DROPDOWN_PRIMARY_WIDTH, render: c => c.name },
      {
        key: 'phone',
        variant: 'meta',
        width: '7rem',
        align: 'end',
        visible: c => !!c.phone,
        render: c => c.phone ?? '',
      },
    ],
    header: {
      columns: [
        { key: 'code', label: 'Mã' },
        { key: 'name', label: 'Tên đối tượng' },
        { key: 'phone', label: 'Điện thoại' },
      ],
    },
    texts: { empty: 'Không tìm thấy đối tượng' },
    ...SEARCH_DROPDOWN_PORTAL,
  };
}
